module biriscv_exec(clk_i, rst_i, opcode_valid_i, opcode_opcode_i,
     opcode_pc_i, opcode_invalid_i, opcode_rd_idx_i, opcode_ra_idx_i,
     opcode_rb_idx_i, opcode_ra_operand_i, opcode_rb_operand_i, hold_i,
     mule_complete_i, mule_result_i, branch_request_o,
     branch_is_taken_o, branch_is_not_taken_o, branch_source_o,
     branch_is_call_o, branch_is_ret_o, branch_is_jmp_o, branch_pc_o,
     branch_d_request_o, branch_d_pc_o, branch_d_priv_o,
     writeback_value_o);
