       mule_complete_i;
  input [31:0] opcode_opcode_i, opcode_pc_i, opcode_ra_operand_i,
       opcode_rb_operand_i, mule_result_i;
  input [4:0] opcode_rd_idx_i, opcode_ra_idx_i, opcode_rb_idx_i;
  output branch_request_o, branch_is_taken_o, branch_is_not_taken_o,
       branch_is_call_o, branch_is_ret_o, branch_is_jmp_o,
       branch_d_request_o;
